MD5 = {'app/engine/transliterator.py': ('b3d3bddf599464445f51ec646ae21763', 'a73d47e2a2fb6e9e0e06e66ed040ff65')}
DEG = {'app/engine/transliterator.py': [('\ndef _kisaltmalar(metin: str) -> str:\n', '\n# Tur Z (2 Kasım 2026), Hayrat verisiyle:\n# 1) Arap harfli kelimeden ya da kapanan tırnaktan sonra boşlukla ayrılmış ek ("قُلْ ün", "“ Kāf ” ın") kelimeye bitişir (Hayrat: ڭ);\n#    "de/da" (bağlaç olabilir) ve "deki" bu kurala girmez.\n# 2) Sebîl’ür-Reşâd (kesme ekten önce) = Sebîlü’r-Reşâd: harf-i tarif kalıbına çevrilir.\n# 3) Cümle içinde "163. madde" sıra sayısıdır: rakam + نجی (Hayrat Risale\'de cümle içinde 75\'te 74). Satır başı (liste: "1. Nota")\n#    ve tarih (27. 05. 1950) dokunulmaz.\n_Z_EK = {"nın": "ڭ", "nin": "ڭ", "nun": "ڭ", "nün": "ڭ", "ın": "ڭ", "in": "ڭ", "un": "ڭ", "ün": "ڭ",\n         "ya": "ه", "ye": "ه", "a": "ه", "e": "ه", "dan": "دن", "den": "دن", "tan": "دن", "ten": "دن",\n         "yı": "ی", "yi": "ی", "ı": "ی", "i": "ی", "yla": "یله", "yle": "یله", "la": "له", "le": "له"}\n_Z_EK_RE = re.compile(r"([\\u0600-\\u06FF][\\u0600-\\u06FF\\u064B-\\u065F\\u0670]*[ \\t]*[”\\"’»]?|[”\\"’»])[ \\t]+("\n                      + "|".join(sorted(_Z_EK, key=len, reverse=True)) + r")(?=[\\s,.;:!?)\\]”\\"]|$)")\n_Z_TARIF_RE = re.compile(r"(\\w)[’\']([üuıi])([lrsştdnz])-(?=\\w)")\n_Z_SIRA_RE = re.compile(r"(?<![\\d.])(\\d{1,4})\\.(?=[ \\t]+[A-Za-zÇĞİÖŞÜçğıöşüÂâÎîÛû])")\n\n\ndef _tur_z(metin: str) -> str:\n    if _os.environ.get("OSM_TUR_Z", "1") == "0":\n        return metin\n\n    def ek(m):\n        once = m.group(1)\n        if not re.search("[\\u0600-\\u06FF]", once) and not re.search("[\\u0600-\\u06FF][ \\t]*$", metin[:m.start(1)]) \\\n                and not re.search(r"\\w[ \\t]*$", metin[:m.start(1)]):\n            return m.group(0)\n        return once.rstrip(" \\t") + _Z_EK[m.group(2)]\n    metin = _Z_EK_RE.sub(ek, metin)\n    metin = _Z_TARIF_RE.sub(lambda m: m.group(1) + m.group(2) + "’" + m.group(3) + "-", metin)\n\n    def sira(m):\n        once = metin[:m.start()].rstrip(" \\t")\n        if not once or once[-1] in ".:;!?)\\n" or re.search(r"\\d[ \\t]*\\.?$", once):\n            return m.group(0)\n        sonra = metin[m.end():].lstrip(" \\t")[:1]\n        if sonra.isupper() and int(m.group(1)) >= 1000:\n            return m.group(0)        # cümle sonundaki yıl (… 1950. Sonra): sıra sayısı değil\n        return m.group(1) + " \\u0646\\u062c\\u06cc"\n    return _Z_SIRA_RE.sub(sira, metin)\n\n\ndef _kisaltmalar(metin: str) -> str:\n'), ('def _kisaltmalar(metin: str) -> str:\n    metin = _sayilari_ayir(metin)\n', 'def _kisaltmalar(metin: str) -> str:\n    metin = _tur_z(metin)\n    metin = _sayilari_ayir(metin)\n'), ('def transliterate_text(turkish_text, *args, **kwargs):\n    if not isinstance(turkish_text, str) or not _YABANCI_HARF_RE.search(turkish_text):\n', 'def transliterate_text(turkish_text, *args, **kwargs):\n    if isinstance(turkish_text, str):\n        turkish_text = _tur_z(turkish_text)   # Tur Z bütün metin üzerinde (iç katmanlar metni parçalara bölüyor); tekrar uygulanması zararsız\n    if not isinstance(turkish_text, str) or not _YABANCI_HARF_RE.search(turkish_text):\n')]}
YENI = {'tests/test_tur_z.py': '"""Tur Z (2 Kasım 2026, Hayrat verisiyle): ayrık ek Arap harfli kelimeye/tırnağa bitişir; Sebîl’ür- = Sebîlü’r-;\ncümle içi sıra sayısı rakam + نجی (Hayrat cümle içinde 75\'te 74); satır başı, tarih ve cümle sonundaki yıl dokunulmaz.\nCalistirma: docker run --rm -v "$PWD":/k -w /k berzahbey/osmanlica-cevirici:latest python tests/test_tur_z.py"""\nimport logging\nimport os\nimport sys\n\nlogging.disable(50)\nsys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "app"))\nfrom engine.transliterator import transliterate_text as T  # noqa: E402\n\nD = [("bu قُلْ ün esası", "بو قُلْڭ اساسی"), ("Sebîl’ür-Reşâd’a yazdı", "سبیل الرّشاده یازدی"),\n     ("olan 163. maddeye ek", "اولان ١٦٣ نجی مادّه\u200cیه اك"), ("ve 29. Mektûb’un altın", "و ٢٩ نجی مكتوبڭ آلتون"),\n     ("Târîh : 27. 05. 1950 Sâat", "تاریخ : ٢٧. ٠٥. ١٩٥٠ ساعت"), ("1. Nota : bu", "١. نوطه : بو"),\n     ("yılında 1950. Sonra geldi", "ییلنده ١٩٥٠. صوڭره كلدی"), ("İşte بِسْمِ اللّٰهِ deki", "ایشته بِسْمِ اللّٰهِ ده\u200cكی")]\n\n\ndef main():\n    kalan = 0\n    for a, b in D:\n        c = T(a).strip()\n        if c != b:\n            kalan += 1\n            print("KALDI", a, "->", c, "(beklenen", b + ")")\n    print("SONUC:", "HEPSI GECTI" if not kalan else f"{kalan} TEST KALDI")\n\n\nmain()\n'}
def md5s(s): return hashlib.md5(s.encode("utf-8")).hexdigest()
if not os.path.isfile("tests/test_tur_w2.py"):
    sys.exit("HATA: önce Tur W-W3 kurulmalı; osmanlica kod klasöründe çalıştırın")
yaz = {}
for p, (e, y) in MD5.items():
    s = open(p, encoding="utf-8", newline="").read()
    if md5s(s) == y:
        print("zaten yamalı:", p); continue
    if md5s(s) != e:
        sys.exit(f"HATA: {p} beklenen sürüm değil (md5 {md5s(s)}); hiçbir dosya değişmedi")
    for a, b in DEG[p]:
        if s.count(a) != 1:
            sys.exit(f"HATA: {p} içinde değişecek yer bulunamadı; hiçbir dosya değişmedi")
        s = s.replace(a, b)
    if md5s(s) != y:
        sys.exit(f"HATA: {p} yamadan sonra md5 tutmadı; hiçbir dosya değişmedi")
    yaz[p] = s
for p, s in yaz.items():
    open(p, "w", encoding="utf-8", newline="").write(s); print("yamalandı:", p)
for p, i in YENI.items():
    open(p, "w", encoding="utf-8", newline="").write(i); print("yazıldı:", p)
print("TAMAM: Tur Z")
